const D = { vi, en };
export let lang = 'vi';
export const LANGS = Object.keys(D);
export function setLang(l) { if (D[l]) lang = l; }
export function has(key) { return key in D[lang] || key in D.en; }
export function t(key, p) {
  let s = D[lang][key];
  if (s === undefined) s = D.en[key];
  if (s === undefined) return key;
  if (p) s = s.replace(/\{(\w+)\}/g, (m, k) => (p[k] === undefined || p[k] === null ? '' : p[k]));
  return s;
}
export const DICT = D;
